find_rule:
js:
var d = [];
var html = getResCode();
var list = pdfa(html, '.bt_img&&ul&&li');
list.forEach(function (it) {
  d.push({
    title: pdfh(it, 'img&&alt') || pdfh(it, 'h3&&Text'),
    desc: pdfh(it, '.jidi&&Text') || pdfh(it, '.hdinfo&&Text'),
    img: pd(it, 'img&&data-original') || pd(it, 'img&&src'),
    url: pd(it, 'a&&href'),
    col_type: 'movie_3_marquee'
  });
});
setResult(d);

searchFind:
