    desc: pdfh(it, '.jidi&&Text') || pdfh(it, '.hdinfo&&Text'),
    img: pd(it, 'img&&data-original') || pd(it, 'img&&src'),
    url: pd(it, 'a&&href')
  });
});
setResult(d);

detail_find_rule:
js:
var d = [];
var html = getResCode();
d.push({
  title: pdfh(html, 'h1&&Text'),
  desc: pdfh(html, '.yp_context&&Text') || pdfh(html, '.moviedteail_list&&Text'),
  img: pd(html, '.dyimg&&img&&src'),
  url: MY_URL,
  col_type: 'movie_1_vertical_pic_blur'
});
var tabs = pdfa(html, '.mi_paly_box&&.ypxingq_t');
var lists = pdfa(html, '.paly_list_btn');
lists.forEach(function (ls, i) {
  d.push({
    title: '““' + (tabs[i] ? pdfh(tabs[i], 'Text') : '线路' + (i + 1)) + '””',
    col_type: 'text_center_1',
    url: 'hiker://empty'
  });
  pdfa(ls, 'body&&a').forEach(function (a) {
    d.push({
      title: pdfh(a, 'Text'),
      url: pd(a, 'a&&href') + $('').lazyRule(function () {
        return 'video://' + input;
      }),
      col_type: 'text_4'
    });
  });
});
setResult(d);
